INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 34, 'theory', 'Quiz: numbers and randomness');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 0, 'Why does 0.1 + 0.2 == 0.3 give False?', '["A Python bug", "Floats are stored in binary with a small error", "You have to write 0,1", "Comparison does not work for floats"]', 1, 'One tenth in binary is an infinite fraction, so the result is approximate. Compare with math.isclose.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 1, 'What is round(2.5)?', '["3", "2", "2.5", "An error"]', 1, 'round goes to the nearest even number: for 2.5 that is 2, for 3.5 it is 4.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 2, 'How do you correctly create a Decimal for 0.1?', '["Decimal(0.1)", "Decimal(\"0.1\")", "Decimal(1 / 10)", "Decimal.of(0.1)"]', 1, 'From a string it is exact; from a float the number already contains the error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 3, 'What does random.seed(42) do?', '["Makes the numbers secure", "Fixes the start of the sequence: results repeat", "Generates the number 42", "Shuffles a list"]', 1, 'With the same seed, random produces the same “random” sequence, which is handy for tests.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 34, 4, 'What should you use to generate a password or a token?', '["random", "secrets", "statistics", "math"]', 1, 'random is predictable; secrets takes randomness from the operating system and is suitable for security.');
